function atomicWriteJson(filePath: string, data: unknown): { written: number; encoding: string; flag: string } {
  const json = JSON.stringify(data, null, 2);
  const tmp = filePath + '.tmp.' + process.pid;
  fs.writeFileSync(tmp, json, { encoding: 'utf8', mode: 0o644 });
  fs.renameSync(tmp, filePath);
  return { written: Buffer.byteLength(json, 'utf8'), encoding: 'utf8', flag: 'w' };
}

