// Implement a type-safe function that unwraps Promises and arrays.
// Given a value that might be a Promise<T> or T[], extract and return
// the inner type. For non-wrapped values, return as-is.
// Use TypeScript's conditional types to provide correct return types.

type UnwrapPromise<T> = T extends Promise<infer U> ? U : T;
type UnwrapArray<T> = T extends Array<infer U> ? U : T;

// Runtime function that extracts values from resolved promises or first array element.
// For plain values, returns the value itself.

golden_completion:
async function unwrap<T>(value: T): Promise<UnwrapPromise<T> | UnwrapArray<T>> {
  if (value instanceof Promise) {
    return await value as any;
  }
  if (Array.isArray(value)) {
    return value[0] as any;
  }
  return value as any;
}

