import * as assert from 'assert';
import { StringDecoder } from 'string_decoder';

function streamDecode(chunks: Buffer[], encoding: BufferEncoding = 'utf8'): {
  result: string;
  hadPartial: boolean;
  flushed: string;
} {
  const decoder = new StringDecoder(encoding);
  let result = '';
  let hadPartial = false;
  for (let i = 0; i < chunks.length; i++) {
    const piece = decoder.write(chunks[i]);
    result += piece;
    if (i < chunks.length - 1 && Buffer.byteLength(piece, encoding) < chunks[i].length) {
      hadPartial = true;
    }
  }
  const flushed = decoder.end();
  result += flushed;
  return { result, hadPartial, flushed };
}

