  view.setFloat32(0, 3.14, false);
  view.setUint16(4, 0xCAFE, true);
  view.setInt32(6, -1, false);
  view.setFloat64(10, 2.718, true);
  return {
    f32: view.getFloat32(0, false),
    u16: view.getUint16(4, true),
    i32: view.getInt32(6, false),
    f64: view.getFloat64(10, true),
    u16BigEndian: view.getUint16(4, false),
  };
}

