interface DateInfo {
    year: number;
    month: number;   // 1-indexed business month
    day: number;
    dayOfWeek: string;
    daysInMonth: number;
}

// Reference: dayOfWeek mapping
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

// Known: Jan 1, 2024 was a Monday
const jan1 = new Date(2024, 0, 1);  // month 0 = January
assert.strictEqual(DAYS[jan1.getDay()], 'Monday');

golden_completion:
function getDateInfo(year: number, businessMonth: number, day: number): DateInfo {
    // Convert 1-indexed business month to 0-indexed JS month
    const date = new Date(year, businessMonth - 1, day);
    // Days in this month: create date for day 0 of NEXT month
    const daysInMonth = new Date(year, businessMonth, 0).getDate();
    return {
        year: date.getFullYear(),
        month: businessMonth,
        day: date.getDate(),
        dayOfWeek: DAYS[date.getDay()],
        daysInMonth
    };
}

